typedef CGAL::Delaunay_triangulation_2<K> DT;

DT dt;
for (const auto& p : points) {
    dt.insert(K::Point_2(p.x(), p.y()));
}

std::vector<std::vector<Point2d>> result;
result.reserve(points.size());

for (const auto& p : points) {
    std::vector<Point2d> cell;
    K::Point_2 site(p.x(), p.y());

    // Find the vertex in the triangulation corresponding to the site
    DT::Vertex_handle vh = dt.nearest_vertex(site);
    if (vh == nullptr) {
        result.push_back(cell);
        continue;
    }

    // Iterate over the faces incident to the vertex
    DT::Face_circulator fc = dt.incident_faces(vh), done = fc;
    if (fc != nullptr) {
        do {
            if (!dt.is_infinite(fc)) {
                K::Point_2 center = dt.dual(fc);
                cell.push_back(Point2d(CGAL::to_double(center.x()), CGAL::to_double(center.y())));
            }
            ++fc;
        } while (fc != done);
    }
    result.push_back(cell);
}

return result;
